<script setup lang="ts">
/**
 * DateRangePicker.RangeCalendar: the popup's month grid, Calendar's anatomy with the range's cells, on Zag's date-picker machine in range mode.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-range-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onMounted, ref, useId, watch } from 'vue'

import * as zag from '@zag-js/date-picker'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { useDirection } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/date-range-picker.module.css'
import Button from './Button.vue'
import type { CalendarDate, CalendarMessages } from './Calendar.vue'
import type { DateRange } from './DateRangePicker.vue'

export interface DateRangePickerRangeCalendarProps {
  /**
   * The committed range, which the grid starts from.
   */
  value: DateRange | null
  minValue?: CalendarDate
  maxValue?: CalendarDate
  isDateUnavailable?: (date: CalendarDate) => boolean
  locale?: string
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  disabled: boolean
  messages: CalendarMessages
  /**
   * The grid's name, before the month on screen.
   */
  label: string
}

defineOptions({ name: 'DateRangePickerRangeCalendar', inheritAttrs: false })

const props = withDefaults(defineProps<DateRangePickerRangeCalendarProps>(), {
  isDateUnavailable: undefined,
})
const emit = defineEmits<{ commit: [range: DateRange]; anchorChange: [anchored: boolean] }>()
const uid = useId()
const travel = ref('next')
const shownMonth = ref('')
const restoring = ref(false)
const language = computed(() => props.locale ?? 'en-US')
const english = computed(() => language.value.toLowerCase().startsWith('en'))
const zone = computed(() => Intl.DateTimeFormat().resolvedOptions().timeZone)
const dayName = computed(
  () => (date: zag.DateValue, text: string, today: boolean, selected: boolean) => {
    if (!english.value) return text
    const said = today
      ? selected
        ? `Today, ${text} selected`
        : `Today, ${text}`
      : selected
        ? `${text} selected`
        : text
    if (props.minValue !== undefined && date.compare(props.minValue) === 0)
      return `${said}, First available date`
    if (props.maxValue !== undefined && date.compare(props.maxValue) === 0)
      return `${said}, Last available date`
    return said
  },
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    inline: true,
    selectionMode: 'range' as const,
    locale: language.value,
    timeZone: zone.value,
    defaultValue: props.value === null ? undefined : [props.value.start, props.value.end],
    min: props.minValue,
    max: props.maxValue,
    startOfWeek: props.firstDayOfWeek,
    disabled: props.disabled,
    isDateUnavailable:
      props.isDateUnavailable === undefined
        ? undefined
        : (date) => props.isDateUnavailable?.(date as zag.CalendarDate) === true,
    onValueChange: (details) => {
      restoring.value
        ? (restoring.value = false)
        : details.value.length === 2 &&
          emit('commit', {
            start: details.value[0] as zag.CalendarDate,
            end: details.value[1] as zag.CalendarDate,
          })
    },
    onVisibleRangeChange: (details) => {
      ;((travel.value =
        shownMonth.value !== '' && details.visibleRange.start.toString() < shownMonth.value
          ? 'previous'
          : 'next'),
        (shownMonth.value = details.visibleRange.start.toString()))
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const named = computed(() =>
  [props.label, api.value.visibleRangeText.formatted].filter(Boolean).join(', '),
)
const previewing = computed(
  () =>
    api.value.value.length === 1 &&
    api.value.weeks.some((week) =>
      week.some((date) => api.value.getDayTableCellState({ value: date }).inHoveredRange),
    ),
)
const dayOf = computed(() => (date: zag.DateValue) => {
  const cell = api.value.getDayTableCellState({ value: date })
  const off = props.disabled || cell.invalid
  const refused = props.isDateUnavailable?.(date as zag.CalendarDate) === true
  const start = previewing.value ? cell.firstInHoveredRange : cell.firstInRange
  const end = previewing.value
    ? cell.lastInHoveredRange
    : api.value.value.length === 1
      ? cell.firstInRange
      : cell.lastInRange
  const inside = (previewing.value ? cell.inHoveredRange : cell.inRange) || start || end
  return {
    date,
    cell,
    off,
    unavailable: refused,
    outside: cell.outsideRange,
    selectable: !off && !refused,
    inside,
    start,
    end,
    middle: inside && !start && !end,
    name: dayName.value(date, cell.valueText, cell.today, inside),
  }
})
const weeks = computed(() => api.value.weeks.map((week) => week.map((date) => dayOf.value(date))))
const cancel = computed(() => (): void => {
  if (api.value.value.length !== 1) return
  const at = api.value.focusedValue
  restoring.value = true
  if (props.value === null) api.value.clearValue({ focus: false })
  else api.value.setValue([props.value.start, props.value.end])
  api.value.setFocusedValue(at)
})
const effect1 = () => {
  shownMonth.value = api.value.visibleRange.start.toString()
}
onMounted(effect1)
const effect2 = () => {
  emit('anchorChange', api.value.value.length === 1)
}
onMounted(effect2)
watch(() => api.value.value.length, effect2, { flush: 'post' })
</script>

<template>
  <div
    v-bind="api.getContentProps()"
    :class="styles.root"
    :hidden="undefined"
    :tabindex="undefined"
    :data-state="undefined"
    role="application"
    :aria-label="named"
  >
    <!-- header -->
    <div :class="styles.header">
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="previous"
        :label="messages.previousMonth"
        :disabled="disabled || api.getPrevTriggerProps().disabled === true"
        @click="api.goToPrev()"
      />
      <!-- title -->
      <span :class="styles.title" aria-live="polite">
        {{ api.visibleRangeText.formatted }}
      </span>
      <Button
        variant="ghost"
        tone="neutral"
        size="sm"
        :iconOnly="true"
        icon="next"
        :label="messages.nextMonth"
        :disabled="disabled || api.getNextTriggerProps().disabled === true"
        @click="api.goToNext()"
      />
    </div>
    <!-- grid -->
    <table
      v-bind="api.getTableProps()"
      :class="styles.grid"
      :key="api.visibleRange.start.toString()"
      :tabindex="undefined"
      :aria-label="named"
      :data-travel="travel"
      @keydown="$event.key === 'Escape' && cancel()"
    >
      <thead aria-hidden="true">
        <tr>
          <template v-for="weekday in api.weekDays" :key="weekday.long">
            <th scope="col" :aria-label="weekday.long">
              <span aria-hidden="true">
                {{ weekday.short }}
              </span>
            </th>
          </template>
        </tr>
      </thead>
      <tbody>
        <template v-for="(week, at) in weeks" :key="at">
          <tr>
            <template v-for="day in week" :key="day.date.toString()">
              <td v-if="day.outside" />
              <td
                v-else
                :class="styles.cell"
                role="gridcell"
                :aria-disabled="!day.selectable ? 'true' : undefined"
                :aria-selected="day.inside ? 'true' : undefined"
              >
                <!-- day -->
                <div
                  v-bind="api.getDayTableCellTriggerProps({ value: day.date })"
                  :class="styles.day"
                  data-calendar-part="day"
                  :aria-label="day.name"
                  :aria-current="day.cell.today ? 'date' : undefined"
                  :tabindex="day.off ? undefined : day.cell.focused ? 0 : -1"
                  :data-selected="undefined"
                  :data-range-start="day.start ? '' : undefined"
                  :data-range-middle="day.middle ? '' : undefined"
                  :data-range-end="day.end ? '' : undefined"
                  :data-today="day.cell.today ? '' : undefined"
                  :data-unavailable="day.unavailable ? '' : undefined"
                  :data-disabled="day.off ? '' : undefined"
                  @focus="api.setFocusedValue(day.date)"
                  @keydown="
                    $event.key === ' ' &&
                    day.selectable &&
                    ($event.preventDefault(), ($event.currentTarget as HTMLElement).click())
                  "
                >
                  {{ day.date.day }}
                </div>
              </td>
            </template>
          </tr>
        </template>
      </tbody>
    </table>
  </div>
</template>
